<?php

declare(strict_types=1);
function site_name(PDO $pdo):string{return setting($pdo,'site_name',(string)app_config('app.name','PinkClub-RakuToys'));}function site_description(PDO $pdo):string{return setting($pdo,'site_description','楽天市場の大人向けグッズを価格・レビュー・送料で比較して探せるサイトです。');}function public_header(PDO $pdo,string $title='',string $description=''):void{$name=site_name($pdo);$pageTitle=$title!==''?$title.'｜'.$name:$name;$desc=$description!==''?$description:site_description($pdo);echo '<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($pageTitle).'</title><meta name="description" content="'.h(mb_substr($desc,0,160)).'"><link rel="stylesheet" href="../assets/site.css"></head><body><header class="site-header"><div class="wrap"><a class="logo" href="./">'.h($name).'</a><nav><a href="./">TOP</a><a href="search.php">商品一覧</a><a href="categories.php">カテゴリ</a><a href="ranking.php">ランキング</a></nav></div></header><main class="wrap">';}function public_footer():void{echo '</main><footer><div class="wrap">価格・在庫・送料などの最新情報は楽天市場の商品ページでご確認ください。</div></footer></body></html>';}function item_card(array $item):void{echo '<article class="card"><a href="item.php?id='.(int)$item['id'].'">';if(!empty($item['image_url']))echo '<img loading="lazy" src="'.h((string)$item['image_url']).'" alt="'.h((string)$item['item_name']).'">';echo '<h3>'.h((string)$item['item_name']).'</h3><div class="price">¥'.number_format((int)$item['item_price']).'</div><div class="rating">★ '.number_format((float)$item['review_average'],2).'（'.number_format((int)$item['review_count']).'件）</div><div class="badges">';if((int)$item['postage_flag']===0)echo '<span>送料無料</span>';echo '</div></a></article>';}
